    describe('Fluent => XML => Fluent', () => {
        test('property with roles round-trips correctly', async () => {
            const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
            const roundTripTest = new FluentXmlFluentTest(project)

            const id = roundTripTest.addId('sys_properties', 'test')
            roundTripTest.addExpectedXmlFileNames(`sys_properties_${id}.xml`)

            roundTripTest.addFluentFragment(`
import { Property } from '@servicenow/sdk/core'

Property({
    $id: Now.ID['test'],
    name: 'x_test.my_property',
    value: 'hello',
    roles: {
        read: ['admin'],
    },
})
`)

            await roundTripTest.verify()
        })
    })

    describe('XML => Fluent => XML', () => {
        test('ACL with roles round-trips correctly', async () => {
            const project = ctx.createProject({ config: { scopeId: 'aaaa1111bbbb2222cccc3333dddd4444' } })
            const id = project.registerExplicitId('sys_properties', 'test')

            const originalFiles = [
                {
                    path: `sys_properties_${id}.xml`,
                    content: `<?xml version="1.0"?>
<record_update>
  <sys_properties action="INSERT_OR_UPDATE">
    <sys_id>${id}</sys_id>
    <sys_scope display_value="x_test">aaaa1111bbbb2222cccc3333dddd4444</sys_scope>
    <description/>
    <ignore_cache>false</ignore_cache>
    <is_private>false</is_private>
    <name>x_test.my_property</name>
    <read_roles>admin</read_roles>
    <suffix>my_property</suffix>
    <type>string</type>
    <value>hello</value>
    <write_roles/>
    <choices/>
  </sys_properties>
</record_update>`,
                },
            ]
            const roundTripTest = new XmlFluentXmlTest(project, __dirname, originalFiles)
            await roundTripTest.verify()
        })
    })
